def solve(rows):
  """Calculates the total cost of rows according to the given rules.

  Args:
    rows: A list of nonnegative integer quantities representing row values.

  Returns:
    The total cost in cents.
  """
  audit_positions = [(i, row) for i, row in enumerate(rows) if i % 4 != 2 or i == len(rows) - 1]

  rotated_rows = []
  if audit_positions:
    last_index = audit_positions[-1][0]
    rotate_by = 2 % (last_index + 1) if last_index + 1 > 0 else 0
    for i, row in audit_positions:
      rotated_rows.append(rows[i - rotate_by])
  else:
    rotated_rows = rows

  total_cost = 0
  for row in rotated_rows:
    if row >= 0:
      cost = 0
      if row <= 15:
        cost = row * 3
      else:
        cost = 15 * 3 + (row - 15) * 2
      if cost <= 58:
        total_cost += cost
      else:
        total_cost += 58

  return total_cost

